package com.hiresense.service;
import com.hiresense.domain.Employee; import com.hiresense.dto.EmployeeDtos.*; import com.hiresense.exception.ApiException; import com.hiresense.repository.EmployeeRepository; import org.apache.commons.csv.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class EmployeeService {private final EmployeeRepository repo;public EmployeeService(EmployeeRepository r){repo=r;}public Page<EmployeeResponse> list(String department,Boolean attrition,int page,int size){Pageable p=PageRequest.of(Math.max(page,0),Math.min(100,Math.max(1,size)));return department!=null?repo.findAllByDepartmentIgnoreCase(department,p).map(this::map):attrition!=null?repo.findAllByAttrition(attrition,p).map(this::map):repo.findAll(p).map(this::map);}
 @Transactional public EmployeeResponse create(EmployeeRequest r){return map(repo.save(copy(new Employee(),r)));}@Transactional public EmployeeResponse update(Long id,EmployeeRequest r){Employee e=repo.findById(id).orElseThrow(()->ApiException.notFound("Employee not found"));return map(repo.save(copy(e,r)));}public void delete(Long id){if(!repo.existsById(id))throw ApiException.notFound("Employee not found");repo.deleteById(id);}
 @Transactional public int importCsv(MultipartFile file){if(file==null||file.isEmpty())throw ApiException.bad("CSV file is required");int n=0;try(Reader r=new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8);CSVParser p=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).setTrim(true).build().parse(r)){for(CSVRecord x:p){EmployeeRequest q=new EmployeeRequest(req(x,"employee_code"),req(x,"full_name"),integer(x,"age"),req(x,"department"),req(x,"job_role"),x.get("business_travel"),decimal(x,"monthly_income"),integer(x,"years_at_company"),integer(x,"total_experience_years"),integer(x,"job_satisfaction"),integer(x,"work_life_balance"),integer(x,"performance_rating"),bool(x,"overtime"),integer(x,"distance_from_home_km"),integer(x,"promotions"),integer(x,"training_times_last_year"),integer(x,"years_in_current_role"),integer(x,"years_since_last_promotion"),integer(x,"years_with_current_manager"),integer(x,"num_companies_worked"),integer(x,"stock_option_level"),integer(x,"percent_salary_hike"),boolObj(x,"attrition"));repo.save(copy(new Employee(),q));n++;}}catch(IOException|IllegalArgumentException e){throw ApiException.bad("Invalid employee CSV: "+e.getMessage());}return n;}
 private Employee copy(Employee e,EmployeeRequest r){e.setEmployeeCode(r.employeeCode());e.setFullName(r.fullName());e.setAge(r.age());e.setDepartment(r.department());e.setJobRole(r.jobRole());e.setBusinessTravel(r.businessTravel());e.setMonthlyIncome(r.monthlyIncome());e.setYearsAtCompany(r.yearsAtCompany());e.setTotalExperienceYears(r.totalExperienceYears());e.setJobSatisfaction(r.jobSatisfaction());e.setWorkLifeBalance(r.workLifeBalance());e.setPerformanceRating(r.performanceRating());e.setOvertime(Boolean.TRUE.equals(r.overtime()));e.setDistanceFromHomeKm(r.distanceFromHomeKm());e.setPromotions(r.promotions());e.setTrainingTimesLastYear(r.trainingTimesLastYear());e.setYearsInCurrentRole(r.yearsInCurrentRole());e.setYearsSinceLastPromotion(r.yearsSinceLastPromotion());e.setYearsWithCurrentManager(r.yearsWithCurrentManager());e.setNumCompaniesWorked(r.numCompaniesWorked());e.setStockOptionLevel(r.stockOptionLevel());e.setPercentSalaryHike(r.percentSalaryHike());e.setAttrition(r.attrition());return e;}
 private String req(CSVRecord r,String k){String v=r.get(k);if(v==null||v.isBlank())throw new IllegalArgumentException("missing "+k);return v;}private Integer integer(CSVRecord r,String k){try{String v=r.get(k);return v==null||v.isBlank()?null:Integer.valueOf(v);}catch(Exception e){return null;}}private BigDecimal decimal(CSVRecord r,String k){try{String v=r.get(k);return v==null||v.isBlank()?null:new BigDecimal(v);}catch(Exception e){return null;}}private boolean bool(CSVRecord r,String k){return Boolean.parseBoolean(r.get(k));}private Boolean boolObj(CSVRecord r,String k){String v=r.get(k);return v==null||v.isBlank()?null:Boolean.valueOf(v);}
 public Employee get(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Employee not found"));}public EmployeeResponse map(Employee e){return new EmployeeResponse(e.getId(),e.getEmployeeCode(),e.getFullName(),e.getAge(),e.getDepartment(),e.getJobRole(),e.getBusinessTravel(),e.getMonthlyIncome(),e.getYearsAtCompany(),e.getTotalExperienceYears(),e.getJobSatisfaction(),e.getWorkLifeBalance(),e.getPerformanceRating(),e.isOvertime(),e.getDistanceFromHomeKm(),e.getPromotions(),e.getTrainingTimesLastYear(),e.getYearsInCurrentRole(),e.getYearsSinceLastPromotion(),e.getYearsWithCurrentManager(),e.getNumCompaniesWorked(),e.getStockOptionLevel(),e.getPercentSalaryHike(),e.getAttrition());}
}
